export type ReportSection = { "section_id": string; "title": string; "role": "introduction" | "methods" | "experiment" | "discussion" | "conclusion" | "appendix"; "blocks": Array<(ReportProseBlock) | (ReportDetailBlock)> };
export type ResearchReport = { "version": 1; "title": string; "sections": Array<ReportSection> };
export type MapPayloadV2 = { "topic": string; "goal_refs": Array<Ref>; "route_refs": Array<Ref>; "result_refs": Array<Ref>; "question_refs": Array<Ref>; "conflict_refs": Array<Ref>; "next_steps": Array<string>; "coverage": { "owner_ids": Array<string>; "source_versions": Array<Ref>; "missing": Array<string> }; "missing_refs"?: Array<UnresolvedRef>; "report"?: ResearchReport };
